class LCT:
    def __init__(self, n={{n}}):
        self.p = [0]*(n+1); self.c = [[0,0] for _ in range(n+1)]
        self.rev = [False]*(n+1)
    def is_root(self, x):
        p = self.p[x]
        return self.c[p][0] != x and self.c[p][1] != x
    def push(self, x):
        if self.rev[x]:
            l, r = self.c[x]
            self.c[x] = [r, l]
            if l: self.rev[l] ^= True
            if r: self.rev[r] ^= True
            self.rev[x] = False
    def rotate(self, x):
        p = self.p[x]; g = self.p[p]
        k = 1 if self.c[p][1] == x else 0
        if not self.is_root(p):
            self.c[g][1 if self.c[g][1]==p else 0] = x
        self.p[x] = g
        self.c[p][k] = self.c[x][k^1]
        if self.c[x][k^1]: self.p[self.c[x][k^1]] = p
        self.c[x][k^1] = p; self.p[p] = x
